package br.com.helptech.agenda;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;import java.text.*;
public class AlarmScheduler {
 static final String STORE="helptech_alarms";
 static PendingIntent pi(Context c,String id,int flags){Intent i=new Intent(c,AlarmReceiver.class);i.setAction("ALARM_"+id);i.putExtra("id",id);return PendingIntent.getBroadcast(c,id.hashCode(),i,flags|PendingIntent.FLAG_IMMUTABLE);}
 static void clear(Context c){android.content.SharedPreferences p=c.getSharedPreferences(STORE,0);String old=p.getString("ids","[]");try{JSONArray arr=new JSONArray(old);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int x=0;x<arr.length();x++)am.cancel(pi(c,arr.getString(x),PendingIntent.FLAG_UPDATE_CURRENT));}catch(Exception ignored){}p.edit().remove("ids").apply();}
 static void schedule(Context c,JSONArray appointments){clear(c);JSONArray ids=new JSONArray();AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long now=System.currentTimeMillis();for(int x=0;x<appointments.length();x++){try{JSONObject a=appointments.getJSONObject(x);String id="appt"+a.optString("id",a.optString("mobile_id",""));String d=a.optString("appt_date")+" "+a.optString("appt_time");SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setLenient(false);long when=f.parse(d).getTime()-3600000L;if(when<=now)continue;Intent i=new Intent(c,AlarmReceiver.class);i.setAction("ALARM_"+id);i.putExtra("id",id);i.putExtra("client",a.optString("client"));i.putExtra("service",a.optString("service"));i.putExtra("time",d);PendingIntent pending=PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pending);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pending);ids.put(id);}catch(Exception ignored){}}c.getSharedPreferences(STORE,0).edit().putString("ids",ids.toString()).apply();}
}
